    im = Image.new("RGB", (1230, 760), "black"); d = ImageDraw.Draw(im)
    for i in range(0, len(dots), 2):
        la, lo = dots[i], dots[i + 1]; x = (lo + 75) * 6; y = (82 - la) * 6
        d.ellipse((x - 1.5, y - 1.5, x + 1.5, y + 1.5), fill="white")
    for n, la, lo, c in caps:
        x = (lo + 75) * 6; y = (82 - la) * 6; d.ellipse((x - 3, y - 3, x + 3, y + 3), fill=(80, 140, 255) if c else (255, 200, 0))
    im.save("/home/claude/shots/landcheck.png")
